{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Moexipril, a close THIQ-based ACE inhibitor with a free carboxylate and N-acyl tetrahydroisoquinoline core, showed no detectable brain radioactivity after systemic administration in rats and dogs, directly supporting poor CNS access for the query's ionized carboxylic acid/THIQ architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enalapril, an ACE inhibitor with a free carboxylate and N-acyl amino acid motif, produced only low levels in rat brain and CSF after acute systemic dosing, supporting poor CNS penetration for the query's similar acidic N-acyl amino acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ramiprilat, a diacid ACE inhibitor, had a free CSF/plasma ratio of only about 0.02 after IV dosing in dogs, indicating very slow and poor blood-brain barrier crossing for ionized carboxylic acid-containing analogues.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "4-DAMP, a permanently charged molecule, showed negligible rat brain uptake, reinforcing that charged species with high polarity have very limited CNS access, consistent with the query's full ionization at physiological pH.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "BINA, a lipophilic carboxylic acid, achieved a brain/plasma ratio of 0.75 in vivo, providing some contradictory evidence that certain acids can access brain; however, its lower similarity, lower molecular weight, and different acid presentation limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest direct analogues with the same ionized carboxylic acid/N-acyl amino acid architecture (moexipril, enalapril, ramiprilat) show absent or very low CNS exposure. The query's additional lipophilic groups are unlikely to overcome full ionization, high molecular weight, and predicted efflux liability, so meaningful CNS access is predicted to fail.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "No experimental transporter interaction data are available for the query.",
    "BINA demonstrates that some lipophilic acids can achieve brain exposure, leaving residual uncertainty about whether the query's lipophilic substituents could enable active uptake."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

